import json,numpy as np
from scipy.spatial.transform import Rotation
s=json.load(open('/app/output/spec.json'))
names=s['proprio']['joints']; axes=np.array(s['proprio']['axis']); centers=np.array(s['proprio']['position_m'])
links=s['links']['names']; parents=s['links']['parent']
# joint i is on link i+1
anc=[]
for k in range(len(names)):
    chain=[]; j=k+1
    while j:
        chain.append(j-1); j=links.index(parents[j])
    anc.append(chain[::-1])
def transform(q,chain):
    T=np.eye(4)
    for i in chain:
        R=Rotation.from_rotvec(axes[i]*q[i]).as_matrix(); U=np.eye(4);U[:3,:3]=R;U[:3,3]=centers[i]-R@centers[i];T=T@U
    return T
def point(q,i,p=None):
    if p is None:p=centers[i]
    T=transform(q,anc[i]); return T[:3,:3]@p+T[:3,3]
def hand(q,side='left',palm=True):
    i=17 if side=='left' else 46
    return point(q,i, np.array([.415,.214 if side=='left' else -.214,.087]))
def com(q):
    cs=np.array(s['links']['com_m']);ms=np.array(s['links']['mass_kg']);ps=[cs[0]]
    for i in range(len(names)):ps.append(point(q,i,cs[i+1]))
    return np.array(ps).T@ms/ms.sum()
if __name__=='__main__':
    m=json.load(open('/app/output/initial/meta.json'));q=np.array(m['proprio']['now'][:69]);print('feet',point(q,4),point(q,9),'hands',hand(q),hand(q,'right'),'COM',com(q))
PY
